변경 이유: 진단의 direction 에 따라 정지/재개 판단 기준을 전방 섹터 거리(d_front)에서 모든 움직이는 점 중 최단 거리(near)로 바꿨습니다. 이제 near < 1.5 m 이면 무조건 정지하고, near > 1.7 m 가 0.3 s 이어져야 재개하므로, 물체가 측면(±90°)으로 빠져 d_front 가 inf 가 되어도 그 물체가 완전히 지나기 전에는 다시 출발하지 않습니다. d_front 는 주행 중 선형 감속에만 쓰고, bearing 변화 감지(측면 통과 즉시 재개) 로직은 호출하지 않도록 지웠습니다. 정지 중 0.9 m 직선 회피와 2 s 강제 탈출은 유지하되, 크리프와 제자리 회전은 near 를 기준으로 막아 측면 물체 쪽으로 다시 들어가지 않게 했습니다.

```python
def controller(t, pose, env):
    """경유점 추종 + 정지/재개 상태 기계 (C-2 시도 9, 진단 반영: d_front -> near).
    - 정지/재개 판단은 방향과 무관한 near(모든 움직이는 점 중 최단 거리)로 한다.
      near < 1.5 m 이면 무조건 정지(v=0, w=0), near > 1.7 m 가 0.3 s 지속되어야 재개한다.
    - d_front(전방 180°, ax > -0.3)는 주행 중 선형 감속(2.0 m -> 1.5 m 에서 0)에만 쓴다.
    - bearing 변화 기반 측면 통과 재개 로직은 제거한다.
    - 정지 중 near < 0.9 m: 직선 후진/전진으로만 비켜남.
    - 정지 누적 2.0 s 초과: near > 1.2 m 이고 d_front > 1.2 m 면 v=0.15 크리프,
      물체가 앞쪽이고 near > 0.9 m 면 제자리 회전(물체 반대쪽), 아니면 정지 유지."""
    if not hasattr(controller, "idx"):
        controller.idx = 0
    dyn_w, dyn_r, raw = _update_sensors(pose)
    if not _NAV["got"]:
        return 0.0, 0.0, False          # 라이다 데이터가 오기 전에는 움직이지 않음

    v, w, done = _nominal(pose)
    if done:
        return 0.0, 0.0, True           # 목표 도착·정렬 완료: 미션 종료

    fx, rx = _BODY[1], _BODY[0]
    d_all = np.hypot(dyn_r[:, 0], dyn_r[:, 1])
    ok = d_all >= _NOISE_R                                    # 0.2 m 미만 잡음 제외
    ax, ays, d = dyn_r[ok, 0], dyn_r[ok, 1], d_all[ok]
    ay = np.abs(ays)

    front = ax > _FRONT_X                                     # 전방 180° (감속 전용)
    d_front = _min_or_inf(d[front])
    near = _min_or_inf(d)                                     # 전 방향 최단 거리 (정지/재개 기준)
    if d.size:
        ni = int(np.argmin(d))
        ox, oy = float(ax[ni]), float(ays[ni])
    else:
        ox, oy = 0.0, 0.0

    # ---- 정지/재개 상태 기계: near < 1.5 정지, near > 1.7 이 0.3 s 지속되면 재개 ----
    if not _NAV["blocked"]:
        if near < _HARD_STOP:
            _NAV["blocked"] = True
            rt, lb = _NAV["resume_t"], _NAV["last_blocked_t"]
            if rt is not None and lb is not None and t - rt < _REBLOCK_T:
                _NAV["blocked_t"] = lb          # 재개 직후 다시 막히면 정지 시간 누적
            else:
                _NAV["blocked_t"] = t
            _NAV["clear_since"] = None
    else:
        resume = False
        if near > _RESUME_D:
            if _NAV["clear_since"] is None:
                _NAV["clear_since"] = t
            if t - _NAV["clear_since"] >= _RESUME_HOLD:
                resume = True
        else:
            _NAV["clear_since"] = None
        if resume:
            _NAV["blocked"] = False
            _NAV["last_blocked_t"] = _NAV["blocked_t"]
            _NAV["resume_t"] = t
            _NAV["blocked_t"] = None
            _NAV["clear_since"] = None

    if _NAV["blocked"]:
        # 정지 중 물체가 0.9 m 안이면 직선으로만 비켜남(앞쪽 물체면 후진, 뒤쪽 물체면 전진)
        if near < _EVADE_R:
            gap_r = _min_or_inf(rx - ax[(ax < rx + 0.05) & (ay < _HW)])
            bx, by = raw[:, 0], np.abs(raw[:, 1])
            rear_free = np.count_nonzero((bx < rx) & (bx > rx - 0.9) & (by < 0.45)) < 3 and gap_r > 0.5
            front_free = np.count_nonzero((bx > fx) & (bx < fx + 0.9) & (by < 0.45)) < 3
            if ox >= 0.5 * (fx + rx):
                if rear_free:
                    return -_EVADE_V, 0.0, False
            elif front_free and d_front >= _HARD_STOP:
                return _EVADE_V, 0.0, False
            return 0.0, 0.0, False
        # 정지 누적 2.0 s 초과 시 강제 탈출 (near 기준으로 안전할 때만)
        if _NAV["blocked_t"] is not None and t - _NAV["blocked_t"] > _ESCAPE_T:
            if near > _CREEP_D and d_front > _CREEP_D:
                cv = _CREEP_V if v > 0.0 else 0.0
                return cv, _clamp(w, -_ESCAPE_W, _ESCAPE_W), False
            if ox > 0.0 and near > _SWEEP_R:
                return 0.0, (-_ESCAPE_W if oy > 0.0 else _ESCAPE_W), False
            return 0.0, 0.0, False
        return 0.0, 0.0, False

    # ---- 주행: d_front 가 2.0 m 안이면 1.5 m 에서 0 이 되도록 선형 감속 (주행 상태에서만) ----
    if v > 0.0:
        if d_front < _SLOW_GAP:
            v = v * _clamp((d_front - _HARD_STOP) / (_SLOW_GAP - _HARD_STOP), 0.0, 1.0)
        if np.any((ax > 0.0) & (ax < 3.5) & (ay < 2.0)):
            v = min(v, 1.0)
    return v, w, False
```
